<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {LayoutDashboard,FolderOpen,Plus,BookOpen,ShieldCheck,ArrowUpRight,LogOut,Building2} from 'lucide-vue-next'
import {api,token} from './api'
import {desk,inr} from './stores/desk'
import type {Case} from './types'
import NewApplication from './pages/NewApplication.vue'
import Workspace from './pages/Workspace.vue'
import StatusBadge from './components/StatusBadge.vue'
const loggedIn=ref(!!token()),credential=ref(''),cases=ref<Case[]>([]),counts=ref<Record<string,number>>({}),total=ref(0),ledger=ref<any[]>([]),selected=ref('')
async function refresh(){desk.busy=true;desk.error='';try{const data=await api('/applications?limit=100');cases.value=data.items;counts.value=data.counts;total.value=data.total;if(desk.view==='ledger')ledger.value=(await api('/ledger?limit=100')).items}catch(e){desk.error=(e as Error).message}finally{desk.busy=false}}
async function login(){sessionStorage.setItem('msme_token',credential.value);try{await api('/applications');loggedIn.value=true;await refresh()}catch(e){sessionStorage.removeItem('msme_token');desk.error=(e as Error).message}}
function logout(){sessionStorage.removeItem('msme_token');loggedIn.value=false;desk.error='';credential.value=''}
async function navigate(view:string){desk.view=view;selected.value='';await refresh()}
function open(id:string){selected.value=id;desk.view='workspace';desk.error=''}
onMounted(()=>{if(loggedIn.value)refresh()})
</script>
<template><div v-if="!loggedIn" class="login-screen"><form class="panel login" @submit.prevent="login"><div class="brand"><div class="brand-mark"><Building2 :size="25"/></div>MSME<span>DESK</span></div><div class="eyebrow">AGENTIC UNDERWRITING</div><h1>Evidence first.<br>Decisions by people.</h1><p>A local workspace for synthetic business loan analysis and review.</p><label>Local development access token<input v-model="credential" type="password" required autocomplete="current-password" placeholder="Enter analyst or reviewer token"></label><p class="error" v-if="desk.error">{{desk.error}}</p><button class="primary">Enter underwriting desk →</button><small>Use the development token configured in your .env file.</small></form></div><div v-else class="shell"><aside><div class="brand"><div class="brand-mark"><Building2 :size="24"/></div>MSME<span>DESK</span></div><div class="nav-caption">WORKSPACE</div><nav><button :class="{active:desk.view==='dashboard'}" @click="navigate('dashboard')"><LayoutDashboard :size="18"/> Overview</button><button :class="{active:['applications','workspace'].includes(desk.view)}" @click="navigate('applications')"><FolderOpen :size="18"/> Applications <span class="nav-count">{{total}}</span></button><button :class="{active:desk.view==='new'}" @click="navigate('new')"><Plus :size="18"/> New application</button><button :class="{active:desk.view==='ledger'}" @click="navigate('ledger')"><BookOpen :size="18"/> Mock ledger</button></nav><div class="sidebar-bottom"><div class="safe-mode"><ShieldCheck :size="18"/><div><strong>Synthetic environment</strong><small>No real lending or payments</small></div></div><button class="logout" @click="logout"><LogOut :size="16"/> Sign out</button><small>UNDERWRITING DESK / MVP 0.1</small></div></aside><div class="main-wrap"><header><div><span class="subtle">Workspace</span><span class="breadcrumb">/</span>{{desk.view==='workspace'?'Case review':desk.view==='new'?'New application':'Underwriting desk'}}</div><div class="header-right"><span class="environment-dot"></span> LOCAL DEMO <span class="avatar">LD</span></div></header><main><div role="alert" v-if="desk.error" class="error-banner">{{desk.error}}<button @click="desk.error=''">Dismiss</button></div><template v-if="desk.view==='dashboard'||desk.view==='applications'"><div class="page-heading"><div><div class="eyebrow">BUSINESS LENDING / SYNTHETIC WORKSPACE</div><h1>{{desk.view==='dashboard'?'Your underwriting overview.':'Applications'}}</h1><p>From source evidence to a considered credit decision.</p></div><button class="primary" @click="navigate('new')"><Plus :size="16"/> New application</button></div><div class="metric-grid four" v-if="desk.view==='dashboard'"><div class="panel"><small>TOTAL APPLICATIONS</small><strong class="metric">{{total}}</strong><span class="metric-caption">Persisted cases</span></div><div class="panel"><small>AWAITING REVIEW</small><strong class="metric green">{{counts.awaiting_review||0}}</strong><span class="metric-caption">Analysis complete</span></div><div class="panel"><small>MORE EVIDENCE</small><strong class="metric">{{counts.needs_evidence||0}}</strong><span class="metric-caption">Clarification required</span></div><div class="panel"><small>PROCESSING FAILURES</small><strong class="metric">{{(counts.failed||0)+(counts.processing_failed||0)}}</strong><span class="metric-caption">Action required</span></div></div><div v-if="desk.view==='dashboard'" class="workflow-banner"><div class="workflow-emblem"><ShieldCheck :size="28"/></div><div><h2>A clear trail behind every decision.</h2><p>Evidence-linked analysis. Deterministic financial tools. A human in control.</p></div><span class="banner-tag">HUMAN REVIEW REQUIRED</span></div><section class="panel"><div class="section-title"><h2>{{desk.view==='dashboard'?'Recent applications':'Application register'}}</h2><button class="text-button" @click="refresh">Refresh ↻</button></div><div class="table-wrap"><table><thead><tr><th>Business / applicant</th><th>Requested amount</th><th>Tenure</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><tr v-for="c in cases" :key="c.id"><td><button class="case-link" @click="open(c.id)">{{c.data.business}}</button><small>{{c.data.applicant}} · {{c.id.slice(0,8)}}</small></td><td>{{inr(c.data.requested_amount)}}</td><td>{{c.data.tenure_months}} months</td><td><StatusBadge :value="c.status"/></td><td>{{new Date(c.created_at).toLocaleDateString('en-IN')}}</td><td><button class="icon-button" aria-label="Open application" @click="open(c.id)"><ArrowUpRight :size="18"/></button></td></tr><tr v-if="!cases.length"><td colspan="6" class="empty"><FolderOpen :size="30"/><h3>{{desk.busy?'Loading applications…':'Your first case starts here.'}}</h3><p>Create an application and add synthetic documents to begin.</p><button @click="navigate('new')">Create application →</button></td></tr></tbody></table></div><div class="table-footer">Showing {{cases.length}} of {{total}} applications · newest first <span>All amounts in INR</span></div></section></template><NewApplication v-if="desk.view==='new'" @created="open"/><Workspace v-if="desk.view==='workspace'" :key="selected" :id="selected"/><template v-if="desk.view==='ledger'"><div class="page-heading"><div><div class="eyebrow">HUMAN-APPROVED / DEMO PROPOSALS</div><h1>Mock ledger</h1><p>Recorded proposals only. No funds move through this desk.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Case</th><th>Principal</th><th>EMI</th><th>Reviewer</th><th>Recorded</th></tr></thead><tbody><tr v-for="entry in ledger"><td><button class="case-link" @click="open(entry.case_id)">{{entry.case_id.slice(0,8)}}</button></td><td>{{inr(entry.data.terms.proposed_principal)}}</td><td>{{inr(entry.data.terms.monthly_installment)}}</td><td>{{entry.data.reviewer_id}}</td><td>{{new Date(entry.created_at).toLocaleString()}}</td></tr><tr v-if="!ledger.length"><td colspan="5" class="empty">No approved demo proposals yet.</td></tr></tbody></table></div></div></template><footer>MSME Underwriting Desk <span>Evidence → Analysis → Human review</span></footer></main></div></div></template>
